import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let $a={a}$ and $m={m}$ be integers greater than one. Let $B$ be a product of $m$ distinct prime numbers, and let $N = B^a$. Let $D$ be the set of all positive divisors of $N$. Define the sums $S_1 = \\sum_{d \\in D} \\log_B(d)$ and $S_2 = \\sum_{d_1 \\in D, d_2 \\in D} \\log_B(\\gcd(d_1, d_2))$. Compute the value of $3 \\cdot \\frac{S_2}{S_1}$.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
a = rng.randint(2, 5)
m = rng.randint(2, 5)
return {
    'a': a,
    'm': m
}

    def verifier(assign):
a = assign['a']
m = assign['m']

if not (isinstance(a, int) and isinstance(m, int)):
    # Parameters must be integers.
    return False, None

if not (a >= 2 and m >= 2):
    # Enforce difficulty by avoiding simpler cases a=1 or m=1.
    return False, None

# The ratio S2/S1 is ((2*a+1)*(a+1)**(m-1))/3.
# The problem asks for 3 * S2/S1.
answer = (2 * a + 1) * (a + 1)**(m - 1)

# The constraints on a and m are small enough that overflow is not an issue.
# a=5, m=5 -> 11 * 6^4 = 14256
# a=5, m=6 -> 11 * 6^5 = 85536
# Maximum possible answer for a=5, m=5 is 14256, which is well within standard integer types.

return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

